import { useState, useEffect, useRef } from "react";
import { X, Save, Sparkles, UploadCloud, RotateCcw, FileText } from "lucide-react";
import axios from "axios";
import "../Style/PropertyDetailsForm.css";

import { useNavigate } from "react-router-dom";
import { ArrowLeft } from "lucide-react";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://localhost:5001";

const initialState = {
  ownerName: "",
  occupierName: "",
  address: "",
  mobile: "",
  ward: "",
  zone: "",
  newPropertyNo: "",
  oldPropertyNo: "",

  usageType: "Residential",
  constructionType: "A",
  constructionYear: "",
  area: "",
  rate: "",

  taxableValue: 0,
  deduction: 0,
  finalTaxableValue: 0,
  propertyTax: 0,
  educationTax: 0,
  treeTax: 0,
  fireTax: 0,
  totalTax: 0,

   latitude: "",
  longitude: ""
};

const AUTOFILL_FIELDS = [
  "ownerName",
  "occupierName",
  "address",
  "mobile",
  "ward",
  "zone",
  "newPropertyNo",
  "oldPropertyNo",
  "usageType",
  "constructionType",
  "constructionYear",
  "area",
  "rate",
  "latitude",
  "longitude"
];

function applyDraftToForm(previousState, draft = {}) {
  const nextState = { ...previousState };

  AUTOFILL_FIELDS.forEach((fieldName) => {
    const value = draft[fieldName];
    const hasValue =
      value !== undefined &&
      value !== null &&
      !(typeof value === "string" && value.trim() === "");

    if (hasValue) {
      nextState[fieldName] = value;
    }
  });

  return nextState;
}

function readFileAsBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = () => {
      const result = String(reader.result || "");
      resolve(result.includes(",") ? result.split(",")[1] : result);
    };

    reader.onerror = () => reject(new Error("Could not read the selected file"));
    reader.readAsDataURL(file);
  });
}

function formatFileSize(sizeInBytes) {
  if (!sizeInBytes && sizeInBytes !== 0) return "";
  if (sizeInBytes < 1024) return `${sizeInBytes} B`;
  if (sizeInBytes < 1024 * 1024) return `${(sizeInBytes / 1024).toFixed(1)} KB`;
  return `${(sizeInBytes / (1024 * 1024)).toFixed(1)} MB`;
}

export default function PropertyDetailsForm({ isOpen, onClose, polygonLocation }) {

  const [formData, setFormData] = useState(initialState);
  const fileInputRef = useRef(null);
  const [documentFile, setDocumentFile] = useState(null);
  const [importStatus, setImportStatus] = useState({
    label: "Ready for upload",
    message: "Upload a scanned property form image or PDF to auto-fill the fields.",
    tone: "idle"
  });
  const [importError, setImportError] = useState("");
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [draftPreview, setDraftPreview] = useState(null);

  useEffect(() => {
  if (polygonLocation) {
    setFormData(prev => ({
      ...prev,
      latitude: polygonLocation.latitude,
      longitude: polygonLocation.longitude
    }));
  }
}, [polygonLocation]);

  const navigate = useNavigate();

  // -------------------------
  // AUTO TAX CALCULATION
  // -------------------------
  useEffect(() => {

    const area = parseFloat(formData.area) || 0;
    const rate = parseFloat(formData.rate) || 0;

    const taxableValue = area * rate;
    const deduction = taxableValue * 0.10;

    const finalTaxableValue = taxableValue - deduction;

    const propertyTax = finalTaxableValue * 0.12;
    const educationTax = finalTaxableValue * 0.02;
    const treeTax = finalTaxableValue * 0.01;
    const fireTax = finalTaxableValue * 0.01;

    const totalTax =
      propertyTax +
      educationTax +
      treeTax +
      fireTax;

    setFormData(prev => ({
      ...prev,
      taxableValue,
      deduction,
      finalTaxableValue,
      propertyTax,
      educationTax,
      treeTax,
      fireTax,
      totalTax
    }));

  }, [formData.area, formData.rate]);

  // This is the document-to-form bridge: upload a scan, let the backend extract
  // structured data, then merge only the filled fields into the current form.
  const handleDocumentImport = async (file) => {
    if (!file) return;

    setDocumentFile(file);
    setIsAnalyzing(true);
    setImportError("");
    setImportStatus({
      label: "Analyzing document",
      message: "Uploading the file for OCR and Gemini-based field extraction.",
      tone: "working"
    });

    try {
      const fileData = await readFileAsBase64(file);

      const response = await axios.post(`${API_BASE_URL}/api/property-details/extract-draft`, {
        fileName: file.name,
        mimeType: file.type || (file.name.toLowerCase().endsWith(".pdf") ? "application/pdf" : "application/octet-stream"),
        fileData,
        formType: "property"
      });

      const draft = response.data?.draft || {};

      setDraftPreview({
        source: response.data?.source || "ai",
        extractedText: response.data?.extractedText || "",
        draft
      });

      setFormData((previousState) => applyDraftToForm(previousState, draft));
      setImportStatus({
        label: "Auto-fill completed",
        message: "Review the extracted values below and adjust anything that needs correction.",
        tone: "success"
      });
    } catch (error) {
      const statusCode = error?.response?.status;
      const rawMessage = error?.response?.data?.message || error.message || "Failed to analyze the uploaded file";
      const quotaMessage =
        statusCode === 429 || /quota|resource_exhausted|too many requests/i.test(rawMessage)
          ? "Gemini quota reached. Wait a bit and try again, or enable billing / increase quota."
          : rawMessage;

      setImportError(quotaMessage);
      setImportStatus({
        label: "Auto-fill unavailable",
        message:
          statusCode === 429
            ? "The scan was understood, but Gemini is rate-limited right now. Manual filling is still available."
            : "You can continue manually. The backend needs Gemini configuration to process scans.",
        tone: "error"
      });
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleDocumentChange = (event) => {
    const file = event.target.files?.[0];
    if (file) {
      handleDocumentImport(file);
    }
  };

  const handleDocumentDrop = (event) => {
    event.preventDefault();
    const file = event.dataTransfer.files?.[0];
    if (file) {
      handleDocumentImport(file);
    }
  };

  const handleDocumentDragOver = (event) => {
    event.preventDefault();
  };

  const openDocumentPicker = () => {
    fileInputRef.current?.click();
  };


  const handleChange = (e) => {

    const { name, value } = e.target;

    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

  };



  // -------------------------
  // SAVE TO BACKEND
  // -------------------------
  const handleSave = async () => {

    try {

      // include polygon geometry if available so backend can persist full polygon
      const payload = { ...formData };
      if (polygonLocation && polygonLocation.geometry) {
        payload.geometry = polygonLocation.geometry;
        payload.polygonCoordinates = polygonLocation.coordinates;
      }

      await axios.post(
        `${API_BASE_URL}/api/property-details`,
        payload
      );

      alert("Property details saved successfully");

      setFormData(initialState);

      onClose();

    } catch (error) {

      console.error(error);

      alert("Failed to save property details");

    }

  };


  if (!isOpen) return null;



  return (
<div className="modal-overlay">
<div className="modal-content professional-form">

        <div className="modal-header">
          <button onClick={() => navigate(0)} className="modal-close-button" aria-label="Back">
            <ArrowLeft size={18} />
          </button>
          <h3 className="modal-title">Main Property Assessment Entry</h3>
          <button onClick={onClose} className="modal-close-button" aria-label="Close">
            <X size={18} />
          </button>
        </div>

<div className="modal-body">

        <section className="document-import-panel" onDrop={handleDocumentDrop} onDragOver={handleDocumentDragOver}>
          <div className="document-import-copy document-import-copy--compact">
            <div className="document-import-eyebrow">
              <Sparkles size={14} />
              <span>Document auto-fill</span>
            </div>
            <h4>Upload hardcopy, auto-fill the form</h4>
            <p>
              If you have a scanned property form, upload it first. Otherwise just continue filling the
              fields manually below.
            </p>
          </div>

          <input
            ref={fileInputRef}
            type="file"
            accept="image/*,.pdf"
            onChange={handleDocumentChange}
            className="document-file-input"
          />

          <button
            type="button"
            className={`document-upload-button ${isAnalyzing ? "is-working" : ""}`}
            onClick={openDocumentPicker}
            onDrop={handleDocumentDrop}
            onDragOver={handleDocumentDragOver}
          >
            <UploadCloud size={20} />
            <span>
              {documentFile ? "Replace uploaded hardcopy" : "Upload hardcopy to auto-fill"}
            </span>
            <small>
              {documentFile
                ? `${documentFile.name} • ${formatFileSize(documentFile.size)}`
                : "PNG, JPG, JPEG, or PDF"}
            </small>
          </button>

          <div className="document-manual-hint">
            No hardcopy? Skip this step and fill the form manually.
          </div>

          <div className="document-import-footer">
            <div className={`document-status document-status--${importStatus.tone}`}>
              <FileText size={14} />
              <div>
                <strong>{importStatus.label}</strong>
                <span>{importStatus.message}</span>
              </div>
            </div>

            <button
              type="button"
              className="button-ghost"
              onClick={() => documentFile && handleDocumentImport(documentFile)}
              disabled={!documentFile || isAnalyzing}
            >
              <RotateCcw size={14} />
              Re-run auto-fill
            </button>
          </div>

          {importError && <div className="document-import-error">{importError}</div>}

          {draftPreview?.draft && (
            <div className="document-preview">
              <div className="document-preview-header">
                <strong>Extracted draft</strong>
                <span>Source: {draftPreview.source}</span>
              </div>

              <div className="document-preview-grid">
                {Object.entries(draftPreview.draft)
                  .filter(([, value]) => value !== undefined && value !== null && String(value).trim() !== "")
                  .slice(0, 6)
                  .map(([key, value]) => (
                    <div key={key} className="document-preview-item">
                      <span>{key}</span>
                      <strong>{String(value)}</strong>
                    </div>
                  ))}
              </div>

              {draftPreview.extractedText && (
                <details className="document-preview-text">
                  <summary>Raw extracted text</summary>
                  <pre>{draftPreview.extractedText}</pre>
                </details>
              )}
            </div>
          )}
        </section>

<fieldset>
<legend>Owner Details</legend>

<div className="form-grid-2">

<div className="form-group">
<label>Owner Name</label>
<input
name="ownerName"
value={formData.ownerName}
onChange={handleChange}
/>
</div>

<div className="form-group">
<label>Occupier Name</label>
<input
name="occupierName"
value={formData.occupierName}
onChange={handleChange}
/>
</div>

<div className="form-group full-width">
<label>Address</label>
<textarea
name="address"
rows="2"
value={formData.address}
onChange={handleChange}
/>
</div>

<div className="form-group">
<label>Mobile</label>
<input
name="mobile"
value={formData.mobile}
onChange={handleChange}
/>
</div>

<div className="form-group">
<label>Ward</label>
<input
name="ward"
value={formData.ward}
onChange={handleChange}
/>
</div>

<div className="form-group">
<label>Zone</label>
<input
name="zone"
value={formData.zone}
onChange={handleChange}
/>
</div>

<div className="form-group">
<label>New Property No</label>
<input
name="newPropertyNo"
value={formData.newPropertyNo}
onChange={handleChange}
/>
</div>

<div className="form-group">
<label>Old Property No</label>
<input
name="oldPropertyNo"
value={formData.oldPropertyNo}
onChange={handleChange}
/>
</div>

</div>
</fieldset>


<fieldset>
<legend>Property Structure</legend>

<div className="form-grid-3">

<div className="form-group">
<label>Usage Type</label>
<select
name="usageType"
value={formData.usageType}
onChange={handleChange}
>
<option>Residential</option>
<option>Commercial</option>
<option>Industrial</option>
</select>
</div>

<div className="form-group">
<label>Construction Type</label>
<select
name="constructionType"
value={formData.constructionType}
onChange={handleChange}
>
<option value="A">A</option>
<option value="B">B</option>
<option value="C">C</option>
<option value="D">D</option>
<option value="E">E</option>
</select>
</div>

<div className="form-group">
<label>Construction Year</label>
<input
type="number"
name="constructionYear"
value={formData.constructionYear}
onChange={handleChange}
/>
</div>

<div className="form-group">
<label>Area (Sq.m)</label>
<input
type="number"
name="area"
value={formData.area}
onChange={handleChange}
/>
</div>

<div className="form-group">
<label>Rate</label>
<input
type="number"
name="rate"
value={formData.rate}
onChange={handleChange}
/>
</div>

</div>
</fieldset>


<fieldset className="tax-section">

<legend>Tax Calculation (System Generated)</legend>

<div className="tax-grid">

<div>
<span>Taxable Value</span>
<strong>₹ {formData.taxableValue.toFixed(2)}</strong>
</div>

<div>
<span>10% Deduction</span>
<strong>₹ {formData.deduction.toFixed(2)}</strong>
</div>

<div>
<span>Final Taxable Value</span>
<strong>₹ {formData.finalTaxableValue.toFixed(2)}</strong>
</div>

<div>
<span>Property Tax</span>
<strong>₹ {formData.propertyTax.toFixed(2)}</strong>
</div>

<div>
<span>Education Tax</span>
<strong>₹ {formData.educationTax.toFixed(2)}</strong>
</div>

<div>
<span>Tree Tax</span>
<strong>₹ {formData.treeTax.toFixed(2)}</strong>
</div>

<div>
<span>Fire Tax</span>
<strong>₹ {formData.fireTax.toFixed(2)}</strong>
</div>

<div className="total-tax">
<span>Total Tax</span>
<strong>₹ {formData.totalTax.toFixed(2)}</strong>
</div>

</div>

</fieldset>

</div>

<div className="modal-footer">

<button onClick={onClose} className="button-secondary">
Cancel
</button>

<button onClick={handleSave} className="button-primary">
<Save size={16}/> Save
</button>

</div>

</div>
</div>
  );
}
